async function loadNumbers(){const status=document.getElementById('numbersStatus'),rows=document.getElementById('numberRows'),button=document.getElementById('refreshNumbers');button.disabled=true;rows.replaceChildren();try{const r=await fetch('api/numbers',{cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not load numbers.');status.textContent=(data.numbers.length?data.numbers.length+' unassigned number(s).':'No unassigned numbers.')+' Airtel inventory checked: '+new Date(data.checkedAt).toLocaleString()+'. Inventory is a saved snapshot, not a live Airtel sync.';for(const number of data.numbers){const row=document.createElement('tr');for(const text of [number,'Airtel','Unassigned']){const cell=document.createElement('td');cell.textContent=text;row.append(cell)}rows.append(row)}}catch(e){status.textContent=e.message}finally{button.disabled=false}}document.getElementById('refreshNumbers').onclick=loadNumbers;loadNumbers();